package ug.audiocity.studio;
import android.app.*;import android.widget.*;import java.util.*;
/** Select a harmonic backing region and suggest this song's scale without altering its audio. */
final class KeyAssist {
 final MainActivity a;KeyAssist(MainActivity activity){a=activity;}
 void choose(Core.Clip vocal,Spinner key,Spinner scale,TextView status,AlertDialog parent){if(!a.canEdit())return;ArrayList<Core.Clip> clips=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();for(Core.Track track:a.session.tracks)for(Core.Clip clip:track.clips)if(clip!=vocal&&clip.length>=Core.RATE*3){clips.add(clip);labels.add(track.name+" / "+clip.name);}if(clips.isEmpty()){new AlertDialog.Builder(a).setTitle("Add your backing first").setMessage("Import the instrumental onto another track, then return to Vocal Tune. Choose a backing with chords or bass, at least three seconds long. You can also set the key manually.").setPositiveButton("OK",null).show();return;}new AlertDialog.Builder(a).setTitle("Choose backing with chords or bass").setItems(labels.toArray(new String[0]),(d,index)->analyse(clips.get(index).copy(),key,scale,status,parent)).setNegativeButton("Cancel",null).show();}
 void analyse(Core.Clip clip,Spinner key,Spinner scale,TextView status,AlertDialog parent){a.engine.pause();status.setText("Analysing backing harmony…");a.busy("Estimating this song's key…",()->{try{final Core.Source source=clip.source;final int offset=clip.offset,length=clip.length;KeyDetector.Result r=KeyDetector.analyse(new Core.Source(){public int frames(){return length;}public float sample(int f,int ch){return source.sample(offset+f,ch);}});a.runOnUiThread(()->{if(a.dead||!parent.isShowing())return;if(r.confident)apply(r,key,scale,status);else{status.setText("Uncertain estimate: "+r.name()+". Keep manual control.");new AlertDialog.Builder(a).setTitle("Check the key suggestion").setMessage("Possible key: "+r.name()+". Another possibility: "+r.alternative()+". Short loops, unusual scales or key changes can make detection uncertain. Listen before tuning the whole vocal.").setPositiveButton("Use suggestion",(d,w)->apply(r,key,scale,status)).setNegativeButton("Keep current",null).show();}});}catch(Exception e){a.runOnUiThread(()->{if(parent.isShowing())status.setText("Key could not be detected. Choose key/scale manually or try a longer backing.");});throw e;}});}
 void apply(KeyDetector.Result r,Spinner key,Spinner scale,TextView status){key.setSelection(r.root);scale.setSelection(r.scale);status.setText("Estimated "+r.name()+" · you can change it. Relative major/minor may share the same notes.");}
}
